const secteurs = $input.first().json.secteurs;
const villes = $input.first().json.villes;
const combinaisons = [];

for (const secteur of secteurs) {
  for (const ville of villes) {
    combinaisons.push({
      json: {
        secteur,
        ville,
        query: `${secteur} ${ville}`,
        score_minimum: $input.first().json.score_minimum,
        secteurs_prioritaires: $input.first().json.secteurs_prioritaires
      }
    });
  }
}

return combinaisons;

const data = $input.first().json;
const results = data.results || [];
const searchParams = $('Combinaisons Secteur x Ville').first().json;

if (!results.length) {
  return [];
}

const entreprises = results.slice(0, 20).map(place => {
  const domainFromWebsite = place.website 
    ? place.website.replace(/^https?:\/\/(www\.)?/, '').split('/')[0]
    : null;

  return {
    json: {
      place_id: place.place_id,
      nom: place.name,
      adresse: place.formatted_address,
      ville: searchParams.ville,
      secteur: searchParams.secteur,
      secteurs_prioritaires: searchParams.secteurs_prioritaires,
      score_minimum: searchParams.score_minimum,
      telephone: place.formatted_phone_number || place.international_phone_number || null,
      website: place.website || null,
      domain: domainFromWebsite,
      rating: place.rating || null,
      user_ratings_total: place.user_ratings_total || 0,
      types: place.types || [],
      business_status: place.business_status || 'OPERATIONAL',
      score: 0,
      signaux: []
    }
  };
}).filter(e => e.json.business_status === 'OPERATIONAL');

return entreprises;

const base = $('Extraire et Normaliser Entreprises').first().json;
const details = $input.first().json;
const result = details.result || {};

const website = result.website || base.website || null;
const domainFromWebsite = website
  ? website.replace(/^https?:\/\/(www\.)?/, '').split('/')[0]
  : null;

return [{
  json: {
    ...base,
    website: website,
    domain: domainFromWebsite,
    telephone: result.formatted_phone_number || result.international_phone_number || base.telephone
  }
}];

const previous = $('Fusionner Détails Place').first().json;
const response = $input.first().json;

let score = previous.score;
let signaux = [...previous.signaux];
let website_status = 'OK';
let tech_detected = [];
let ssl_valid = false;
let has_google_ads = false;

// Vérification du statut HTTP
const statusCode = response.statusCode || 0;
if (statusCode === 0 || statusCode >= 500) {
  score += 2;
  signaux.push('🟠 Site web inaccessible/erreur (+2)');
  website_status = 'ERROR';
} else if (statusCode >= 400) {
  score += 2;
  signaux.push('🟠 Site web retourne erreur ' + statusCode + ' (+2)');
  website_status = 'ERROR';
} else {
  website_status = 'OK';
}

// Vérification SSL
const url = previous.website || '';
if (url.startsWith('https://')) {
  ssl_valid = true;
} else if (url.startsWith('http://')) {
  score += 1;
  signaux.push('🟡 Pas de SSL / HTTP seulement (+1)');
  ssl_valid = false;
}

// Analyse du contenu pour détecter les technologies
const body = (response.data || '').toLowerCase();

// Détection WordPress (site souvent vieux ou peu optimisé)
if (body.includes('wp-content') || body.includes('wp-includes')) {
  tech_detected.push('WordPress');
}

// Détection Wix/Jimdo/Weebly (constructeurs = faible perf potentielle)
if (body.includes('wixsite.com') || body.includes('wix.com/')) {
  tech_detected.push('Wix');
  score += 1;
  signaux.push('🟡 Site sur Wix (optimisation possible) (+1)');
}
if (body.includes('jimdo.com') || body.includes('jimdofree.com')) {
  tech_detected.push('Jimdo');
  score += 1;
  signaux.push('🟡 Site sur Jimdo (+1)');
}

// Détection Google Ads (gtag ou adsbygoogle)
if (body.includes('googletagmanager.com') || body.includes('gtag(') || body.includes('google_tag_manager')) {
  tech_detected.push('Google Tag Manager');
}
if (body.includes('adsbygoogle') || body.includes('googlesyndication.com')) {
  tech_detected.push('Google Ads Display');
  has_google_ads = true;
}
if (body.includes('google_conversion') || body.includes('googleadservices.com')) {
  tech_detected.push('Google Ads Conversion');
  has_google_ads = true;
}

// Pas de Google Ads = opportunité
if (!has_google_ads) {
  score += 2;
  signaux.push('🟢 Aucune campagne Google Ads détectée (+2)');
} else {
  signaux.push('ℹ️ Google Ads actif détecté (déjà client ou concurrent)');
}

// Site sans copyright récent = site potentiellement vieux
const yearMatch = body.match(/copyright[^\d]*(20\d{2})/i) || body.match(/©[^\d]*(20\d{2})/);
if (yearMatch) {
  const siteYear = parseInt(yearMatch[1]);
  const currentYear = new Date().getFullYear();
  if (currentYear - siteYear >= 4) {
    score += 1;
    signaux.push(`🟡 Site web ancien (${siteYear}) - refonte possible (+1)`);
  }
}

return [{
  json: {
    ...previous,
    score,
    signaux,
    website_status,
    ssl_valid,
    tech_detected,
    has_google_ads
  }
}];

const data = $input.first().json;
let score = data.score || 0;
let signaux = [...(data.signaux || [])];

const secteursPrioritaires = data.secteurs_prioritaires || [];
const secteur = (data.secteur || '').toLowerCase();

const estPrioritaire = secteursPrioritaires.some(
  s => secteur.includes(s.toLowerCase()) || s.toLowerCase().includes(secteur)
);

if (estPrioritaire) {
  score += 2;
  signaux.push(`🎯 Secteur prioritaire: ${data.secteur} (+2)`);
}

return [{ json: { ...data, score, signaux } }];

const previous = $('Score Secteur Prioritaire').first().json;
const ftData = $input.first().json;

let score = previous.score || 0;
let signaux = [...(previous.signaux || [])];

// France Travail
const ftOffres = ftData.resultats || [];
const nbFT = ftOffres.length;

if (nbFT > 0) {
  score += 2;
  signaux.push(`💼 ${nbFT} offre(s) France Travail récentes (+2)`);
}

return [{
  json: {
    ...previous,
    score,
    signaux,
    offres_france_travail: nbFT
  }
}];

const data = $input.first().json;
let score = data.score || 0;
let signaux = [...(data.signaux || [])];

// Estimation de taille via le nombre d'avis Google
// Peu d'avis = petite structure locale = cible idéale
const nbAvis = data.user_ratings_total || 0;

if (nbAvis < 50) {
  score += 1;
  signaux.push(`📊 Petite structure estimée (${nbAvis} avis Google) (+1)`);
} else if (nbAvis > 500) {
  // Grande entreprise = moins pertinent
  score -= 1;
  signaux.push(`📊 Structure potentiellement grande (${nbAvis} avis) (-1)`);
}

return [{ json: { ...data, score, signaux, estimation_nb_avis: nbAvis } }];

const previous = $('Filtrer Score Minimum').first().json;
const hunterData = $input.first().json;

let contact_email = null;
let contact_nom = null;
let contact_prenom = null;
let contact_poste = null;
let email_confidence = 0;

const data = hunterData.data || {};
const emails = data.emails || [];

// Rôles cibles en priorité
const rolesPrioritaires = [
  'directeur', 'dirigeant', 'gérant', 'president', 'ceo', 'coo',
  'responsable', 'manager', 'marketing', 'communication', 'rh', 'recrutement',
  'fondateur', 'founder', 'associé', 'partner'
];

let meilleurContact = null;
let meilleurScore = -1;

for (const email of emails) {
  const position = (email.position || '').toLowerCase();
  let positionScore = 0;

  for (const role of rolesPrioritaires) {
    if (position.includes(role)) {
      positionScore = rolesPrioritaires.indexOf(role);
      break;
    }
  }

  // Favoriser les emails avec haute confiance
  const confidenceBonus = (email.confidence || 0) / 20;
  const totalScore = (10 - positionScore) + confidenceBonus;

  if (totalScore > meilleurScore) {
    meilleurScore = totalScore;
    meilleurContact = email;
  }
}

if (meilleurContact) {
  contact_email = meilleurContact.value;
  contact_nom = meilleurContact.last_name;
  contact_prenom = meilleurContact.first_name;
  contact_poste = meilleurContact.position;
  email_confidence = meilleurContact.confidence || 0;
}

// Pattern d'email générique si aucun contact
const domain_pattern = data.pattern ? `${data.pattern}@${data.domain}` : null;

return [{
  json: {
    ...previous,
    contact_email,
    contact_nom,
    contact_prenom,
    contact_poste,
    email_confidence,
    domain_pattern,
    total_emails_trouves: emails.length
  }
}];

const d = $input.first().json;
const now = new Date().toLocaleDateString('fr-FR', { 
  day: '2-digit', month: '2-digit', year: 'numeric',
  hour: '2-digit', minute: '2-digit'
});

const signaux_str = (d.signaux || []).join(' | ');
const tech_str = (d.tech_detected || []).join(', ');

// Niveau de priorité
let priorite;
if (d.score >= 8) priorite = '🔥 TRÈS HAUTE';
else if (d.score >= 6) priorite = '⚡ HAUTE';
else if (d.score >= 4) priorite = '✅ MOYENNE';
else priorite = '⬇️ BASSE';

return [{
  json: {
    // Colonnes Google Sheets
    date_detection: now,
    priorite: priorite,
    score: d.score,
    nom_entreprise: d.nom || '',
    secteur: d.secteur || '',
    ville: d.ville || '',
    telephone: d.telephone || '',
    website: d.website || 'ABSENT',
    website_status: d.website_status || '',
    ssl: d.ssl_valid ? 'Oui' : 'Non',
    technologies: tech_str,
    google_ads: d.has_google_ads ? 'Oui' : 'Non',
    offres_emploi: d.offres_france_travail || 0,
    contact_prenom: d.contact_prenom || '',
    contact_nom: d.contact_nom || '',
    contact_email: d.contact_email || d.domain_pattern || '',
    contact_poste: d.contact_poste || '',
    email_confiance: d.email_confidence ? `${d.email_confidence}%` : '',
    signaux_detectes: signaux_str,
    statut: 'À contacter',
    notes: '',
    // Données brutes pour filtrage ultérieur
    _raw: {
      place_id: d.place_id,
      domain: d.domain,
      score: d.score
    }
  }
}];

